import React from 'react';
import { Nav } from 'react-bootstrap';
import { Link, useLocation } from 'react-router-dom';
import { getUserRole } from '../../utils/auth';
import { USER_ROLES } from '../../utils/constants';

const Sidebar = () => {
  const location = useLocation();
  const userRole = getUserRole();

  const isActive = (path) => location.pathname === path;

  const renderUserMenu = () => (
    <>
      <Nav.Link as={Link} to="/user/dashboard" className={isActive('/user/dashboard') ? 'active' : ''}>
        <i className="fas fa-tachometer-alt me-2"></i>
        Dashboard
      </Nav.Link>
      <Nav.Link as={Link} to="/user/booking" className={isActive('/user/booking') ? 'active' : ''}>
        <i className="fas fa-plus-circle me-2"></i>
        Buat Booking
      </Nav.Link>
      <Nav.Link as={Link} to="/user/mybookings" className={isActive('/user/mybookings') ? 'active' : ''}>
        <i className="fas fa-list me-2"></i>
        Booking Saya
      </Nav.Link>
    </>
  );

  const renderAdminMenu = () => (
    <>
      <Nav.Link as={Link} to="/admin/dashboard" className={isActive('/admin/dashboard') ? 'active' : ''}>
        <i className="fas fa-tachometer-alt me-2"></i>
        Dashboard Admin
      </Nav.Link>
      <Nav.Link as={Link} to="/admin/bookings" className={isActive('/admin/bookings') ? 'active' : ''}>
        <i className="fas fa-calendar-check me-2"></i>
        Kelola Booking
      </Nav.Link>
      <Nav.Link as={Link} to="/admin/zoom" className={isActive('/admin/zoom') ? 'active' : ''}>
        <i className="fas fa-video me-2"></i>
        Kelola Zoom
      </Nav.Link>
    </>
  );

  const renderLogistikMenu = () => (
    <>
      <Nav.Link as={Link} to="/logistik/dashboard" className={isActive('/logistik/dashboard') ? 'active' : ''}>
        <i className="fas fa-tachometer-alt me-2"></i>
        Dashboard Logistik
      </Nav.Link>
      <Nav.Link as={Link} to="/logistik/bookings" className={isActive('/logistik/bookings') ? 'active' : ''}>
        <i className="fas fa-door-open me-2"></i>
        Booking Ruangan
      </Nav.Link>
      <Nav.Link as={Link} to="/logistik/rooms" className={isActive('/logistik/rooms') ? 'active' : ''}>
        <i className="fas fa-building me-2"></i>
        Kelola Ruangan
      </Nav.Link>
    </>
  );

  return (
    <div className="sidebar bg-light min-vh-100 p-3 border-end">
      <Nav className="flex-column">
        {userRole === USER_ROLES.USER && renderUserMenu()}
        {userRole === USER_ROLES.ADMIN && renderAdminMenu()}
        {userRole === USER_ROLES.LOGISTIK && renderLogistikMenu()}
      </Nav>
    </div>
  );
};

export default Sidebar;
